import csv,gzip,math
from urllib.request import Request,urlopen
from openpyxl import load_workbook
import numpy as np

expr_path='$(inputs.expression.path)'
with open(expr_path,'rb') as fh: magic=fh.read(2)
opener=gzip.open if magic==b'\x1f\x8b' else open
genes=[]; rows=[]
with opener(expr_path,'rt',newline='') as fh:
    rd=csv.reader(fh,delimiter='\t'); header=next(rd); labels=header[1:]
    for r in rd:
        if r:
            genes.append(r[0]); rows.append([float(x) for x in r[1:]])
X=np.asarray(rows,dtype=float)
finite=np.all(np.isfinite(X),axis=1)
X=X[finite]
genes=[g for g,k in zip(genes,finite) if k]
logX=np.log1p(np.maximum(X,0))
mu=logX.mean(axis=1,keepdims=True); sd=logX.std(axis=1,keepdims=True)
Z=np.divide(logX-mu,sd,out=np.zeros_like(logX),where=sd>0)
gene_to_i={g:i for i,g in enumerate(genes)}

url='https://ars.els-cdn.com/content/image/1-s2.0-S2211124725000117-mmc5.xlsx'
req=Request(url,headers={'User-Agent':'Mozilla/5.0','Referer':'https://www.cell.com/'})
open('mmc5.xlsx','wb').write(urlopen(req,timeout=90).read())
ws=load_workbook('mmc5.xlsx',read_only=True,data_only=True)['Table S4']
it=ws.iter_rows(values_only=True); h=list(next(it)); ix={str(v):i for i,v in enumerate(h)}
by_cluster={i:[] for i in range(15)}
for r in it:
    try:
        g=str(r[ix['Gene_ID']]); fc=float(r[ix['avg_log2FC']]); padj=float(r[ix['p_val_adj']]); c=int(r[ix['cluster']])
    except Exception: continue
    if c in by_cluster and math.isfinite(fc) and math.isfinite(padj) and padj<0.05 and fc>0.25 and g in gene_to_i:
        by_cluster[c].append((g,fc))
for c in by_cluster: by_cluster[c].sort(key=lambda t:(-t[1],t[0]))

groups={'cortex':[2],'endodermis':[9],'epidermis':[1,5,7],'meristems':[0,3,12],'pericycle':[6],'phloem':[11,13],'provascular':[4],'root_cap':[14],'root_hair':[8],'xylem':[10]}
types=list(groups); depths=[20,50,100,200,500]

def max_assignment(S):
    n=S.shape[0]; dp={0:(0.0,[])}
    for i in range(n):
        nd={}
        for mask,(score,cols) in dp.items():
            for j in range(n):
                if not mask>>j&1:
                    nm=mask|1<<j; ns=score+float(S[i,j])
                    if nm not in nd or ns>nd[nm][0]: nd[nm]=(ns,cols+[j])
        dp=nd
    return dp[(1<<n)-1]

score_by_depth={}; assignments={}; swap_by_depth={}; counts_by_depth={}
for depth in depths:
    S=np.zeros((len(types),len(labels))); counts={}
    for ti,t in enumerate(types):
        best={}
        for c in groups[t]:
            for g,fc in by_cluster[c]:
                if g not in best or fc>best[g]: best[g]=fc
        selected=sorted(best,key=lambda g:(-best[g],g))[:depth]
        ids=[gene_to_i[g] for g in selected]
        counts[t]=len(ids)
        S[ti,:]=Z[ids,:].mean(axis=0) if ids else -99.0
    S=np.nan_to_num(S,nan=-99.0,posinf=99.0,neginf=-99.0)
    score_by_depth[depth]=S; counts_by_depth[depth]=counts
    _,cols=max_assignment(S)
    pred={labels[cols[i]]:types[i] for i in range(len(types))}
    assignments[depth]=pred
    base=sum(S[types.index(l),labels.index(l)] for l in labels)
    candidates=[(0.0,None)]
    for a in range(len(labels)):
      for b in range(a+1,len(labels)):
        gain=-S[types.index(labels[a]),a]-S[types.index(labels[b]),b]+S[types.index(labels[b]),a]+S[types.index(labels[a]),b]
        candidates.append((float(gain),(labels[a],labels[b])))
    swap_by_depth[depth]=max(candidates,key=lambda x:x[0])

Cs=[]
for S in score_by_depth.values():
    sm=S.mean(axis=1,keepdims=True); ss=S.std(axis=1,keepdims=True)
    Cs.append((S-sm)/np.where(ss==0,1,ss))
C=np.mean(Cs,axis=0)
_,cols=max_assignment(C)
cons={labels[cols[i]]:types[i] for i in range(len(types))}
base=sum(C[types.index(l),labels.index(l)] for l in labels)
pairs=[]
for a in range(len(labels)):
  for b in range(a+1,len(labels)):
    gain=-C[types.index(labels[a]),a]-C[types.index(labels[b]),b]+C[types.index(labels[b]),a]+C[types.index(labels[a]),b]
    pairs.append((float(gain),labels[a],labels[b]))
pairs.sort(reverse=True)

with open('swap_diagnostics.txt','w') as out:
    out.write(f'MATRIX\tgenes_total={len(rows)}\tgenes_finite={len(genes)}\tcolumns={len(labels)}\tlabels={",".join(labels)}\n')
    out.write('CLUSTER_DEG_COUNTS\t'+'\t'.join(f'{c}:{len(by_cluster[c])}' for c in range(15))+'\n')
    for depth in depths:
        pair,gain=swap_by_depth[depth]
        out.write(f'DEPTH\t{depth}\tMARKERS\t'+','.join(f'{t}:{counts_by_depth[depth][t]}' for t in types)+f'\tBEST_SWAP\t{pair}\tGAIN\t{gain:.6f}\n')
        out.write('ASSIGNMENT\t'+';'.join(f'{lab}->{assignments[depth][lab]}' for lab in labels)+'\n')
    out.write('CONSENSUS_ASSIGNMENT\t'+';'.join(f'{lab}->{cons[lab]}' for lab in labels)+'\n')
    out.write('TOP_TRANSPOSITIONS\n')
    for gain,a,b in pairs[:8]: out.write(f'{a},{b}\t{gain:.6f}\n')
    out.write('CONSENSUS_SCORE_MATRIX\n')
    out.write('reference_observed\t'+'\t'.join(labels)+'\n')
    for i,t in enumerate(types): out.write(t+'\t'+'\t'.join(f'{v:.3f}' for v in C[i])+'\n')
