u='https://ars.els-cdn.com/content/image/1-s2.0-S2211124725000117-mmc5.xlsx'
b=urlopen(Request(u,headers={'User-Agent':'Mozilla/5.0','Referer':'https://www.cell.com/'}),timeout=90).read(); open('m.xlsx','wb').write(b)
ws=load_workbook('m.xlsx',read_only=True,data_only=True)['Table S4']; it=ws.iter_rows(values_only=True); h=list(next(it)); ix={str(v):i for i,v in enumerate(h)}
bc={i:[] for i in range(15)}
for r in it:
 try: g=str(r[ix['Gene_ID']]); fc=float(r[ix['avg_log2FC']]); p=float(r[ix['p_val_adj']]); c=int(str(r[ix['cluster']]).split()[0])
 except Exception: continue
 if c in bc and math.isfinite(fc) and math.isfinite(p) and p<.05 and fc>.25 and g in gi: bc[c].append((g,fc))
for c in bc: bc[c].sort(key=lambda t:(-t[1],t[0]))
groups={'cortex':[2],'endodermis':[9],'epidermis':[1,5,7],'meristems':[0,3,12],'pericycle':[6],'phloem':[11,13],'provascular':[4],'root_cap':[14],'root_hair':[8],'xylem':[10]}
types=list(groups); depths=[20,50,100,200,500]
def assign(S):
 n=len(S); dp={0:(0.,[])}
 for i in range(n):
  nd={}
  for m,(sc,cols) in dp.items():
   for j in range(n):
    if not (m>>j)&1:
     nm=m|1<<j; ns=sc+float(S[i,j])
     if nm not in nd or ns>nd[nm][0]: nd[nm]=(ns,cols+[j])
  dp=nd
 return dp[(1<<n)-1]
score={}; preds={}; swaps={}; counts={}
for d in depths:
 S=np.zeros((10,10)); counts[d]={}
 for i,t in enumerate(types):
  best={}
  for c in groups[t]:
   for g,fc in bc[c]:
    if g not in best or fc>best[g]: best[g]=fc
  sel=sorted(best,key=lambda g:(-best[g],g))[:d]; ids=[gi[g] for g in sel]; counts[d][t]=len(ids)
  S[i]=Z[ids].mean(0) if ids else -99.
 score[d]=np.nan_to_num(S,nan=-99.,posinf=99.,neginf=-99.); _,cols=assign(score[d]); preds[d]={labels[cols[i]]:types[i] for i in range(10)}
 cand=[(0.,None)]
 for a in range(10):
  for b in range(a+1,10):
   gain=-S[types.index(labels[a]),a]-S[types.index(labels[b]),b]+S[types.index(labels[b]),a]+S[types.index(labels[a]),b]
   cand.append((float(gain),(labels[a],labels[b])))
 swaps[d]=max(cand,key=lambda x:x[0])
Cs=[]
for S in score.values():
 sm=S.mean(1,keepdims=True); ss=S.std(1,keepdims=True); Cs.append((S-sm)/np.where(ss==0,1,ss))
C=np.mean(Cs,0); _,cols=assign(C); cons={labels[cols[i]]:types[i] for i in range(10)}
pairs=[]
for a in range(10):
 for b in range(a+1,10):
  gain=-C[types.index(labels[a]),a]-C[types.index(labels[b]),b]+C[types.index(labels[b]),a]+C[types.index(labels[a]),b]
  pairs.append((float(gain),labels[a],labels[b]))
pairs.sort(reverse=True)
with open('swap_diagnostics.txt','w') as out:
 out.write(f'MATRIX\tgenes_total={len(rows)}\tgenes_finite={len(genes)}\tcolumns={len(labels)}\tlabels={",".join(labels)}\n')
 out.write('CLUSTER_DEG_COUNTS\t'+'\t'.join(f'{c}:{len(bc[c])}' for c in range(15))+'\n')
 for d in depths:
  gain,pair=swaps[d]; out.write(f'DEPTH\t{d}\tMARKERS\t'+','.join(f'{t}:{counts[d][t]}' for t in types)+f'\tBEST_SWAP\t{pair}\tGAIN\t{gain:.6f}\n')
  out.write('ASSIGNMENT\t'+';'.join(f'{lab}->{preds[d][lab]}' for lab in labels)+'\n')
 out.write('CONSENSUS_ASSIGNMENT\t'+';'.join(f'{lab}->{cons[lab]}' for lab in labels)+'\nTOP_TRANSPOSITIONS\n')
 for gain,a,b in pairs[:8]: out.write(f'{a},{b}\t{gain:.6f}\n')
 out.write('CONSENSUS_SCORE_MATRIX\nreference_observed\t'+'\t'.join(labels)+'\n')
 for i,t in enumerate(types): out.write(t+'\t'+'\t'.join(f'{v:.3f}' for v in C[i])+'\n')
