import csv,gzip,re
from urllib.request import Request,urlopen
from openpyxl import load_workbook
import numpy as np
p='$(inputs.expression.path)'
with open(p,'rb') as f: mg=f.read(2)
op=gzip.open if mg==b'\x1f\x8b' else open
genes=[]; rows=[]
with op(p,'rt',newline='') as f:
 rd=csv.reader(f,delimiter='\t'); labs=next(rd)[1:]
 for r in rd:
  if r: genes.append(r[0]); rows.append([float(x) for x in r[1:]])
X=np.asarray(rows,float); L=np.log1p(np.maximum(X,0)); mu=L.mean(1,keepdims=True); sd=L.std(1,keepdims=True)
Z=np.divide(L-mu,sd,out=np.zeros_like(L),where=sd>0); gi={g:i for i,g in enumerate(genes)}
base='https://ars.els-cdn.com/content/image/1-s2.0-S2211124725000117-'; hdr={'User-Agent':'Mozilla/5.0','Referer':'https://www.cell.com/'}
def wb(name):
 b=urlopen(Request(base+name,headers=hdr),timeout=90).read(); open(name,'wb').write(b)
 return load_workbook(name,read_only=True,data_only=True)
def norm(x):
 s=str(x).strip().lower().replace(' ','_').replace('/','_')
 mp={'root_cap':'root_cap','epidermis':'epidermis','cortex':'cortex','endodermis':'endodermis','pericycle':'pericycle','xylem':'xylem','phloem':'phloem','provascular':'provascular','g1_s':'meristems','g2_m':'meristems'}
 return mp.get(s,s)
def extract_ids(v):
 if v is None: return []
 return re.findall(r'TraesCS[A-Za-z0-9]+(?:LC)?',str(v))
refs={}
# Conserved cross-species marker ranking
ws=wb('mmc10.xlsx')['T. aestivum']; it=ws.iter_rows(values_only=True); h=list(next(it)); ix={str(v):i for i,v in enumerate(h)}
for r in it:
 try: t=norm(r[ix['Cell type']]); rank=float(r[ix['Rank']]); present=bool(r[ix['T. aestivum']])
 except Exception: continue
 if t in labs and present and rank<=500:
  refs.setdefault('conserved',{}).setdefault(t,[]).extend(extract_ids(r[ix['Best marker']])+extract_ids(r[ix['Other markers']]))
# Spatially validated marker lists
ws=wb('mmc6.xlsx')['Table S5']; it=ws.iter_rows(values_only=True); h=list(next(it)); current=None
for r in it:
 if r[0] is not None: current=norm(r[0])
 if current in labs:
  refs.setdefault('spatial',{}).setdefault(current,[]).extend(extract_ids(r[1])+extract_ids(r[3]))
# deduplicate and score
with open('acceptance.txt','w') as out:
 for source,sets in refs.items():
  out.write('SOURCE\t'+source+'\n')
  types=[t for t in labs if t in sets]
  S=np.zeros((len(types),len(labs)))
  for i,t in enumerate(types):
   ids=[]; seen=set()
   for g in sets[t]:
    if g in gi and g not in seen: ids.append(gi[g]); seen.add(g)
   S[i]=Z[ids].mean(0) if ids else -99
   best=int(np.argmax(S[i])); own=labs.index(t)
   out.write(f'MATCH\t{t}\tmarkers={len(ids)}\tbest={labs[best]}\tbest_score={S[i,best]:.4f}\town_score={S[i,own]:.4f}\tmargin={S[i,own]-max(np.delete(S[i],own)):.4f}\n')
  out.write('SCORE_MATRIX\nreference_observed\t'+'\t'.join(labs)+'\n')
  for i,t in enumerate(types): out.write(t+'\t'+'\t'.join(f'{v:.3f}' for v in S[i])+'\n')
